<?php namespace app\controllers; use Yii; use yii\web\Controller; use app\models\Nilai; use app\models\Kriteria; use app\models\Mahasiswa; use app\models\Dosen;
class NilaiController extends Controller {
 public function actionCreate(){ $m=new Nilai(['tanggal'=>date('Y-m-d')]); $ks=Kriteria::find()->orderBy(['id'=>SORT_ASC])->all(); if($m->load(Yii::$app->request->post())){ $scores=Yii::$app->request->post('score',[]); $m->nilai_data=json_encode($scores); $m->total=$m->hitungTotal(); if($m->save()) return $this->redirect(['site/index']); } return $this->render('form',['model'=>$m,'kriteria'=>$ks,'mahasiswa'=>Mahasiswa::find()->all(),'dosen'=>Dosen::find()->all()]); }
 public function actionDelete($id){if($m=Nilai::findOne($id))$m->delete(); return $this->redirect(['site/index']);}
 public function actionExport(){ $rows=Nilai::find()->with(['mahasiswa','dosen'])->all(); Yii::$app->response->format=\yii\web\Response::FORMAT_RAW; Yii::$app->response->headers->set('Content-Type','text/csv; charset=UTF-8'); Yii::$app->response->headers->set('Content-Disposition','attachment; filename="nilai_sidang.csv"'); $out=fopen('php://output','w'); fputcsv($out,['NIM','Mahasiswa','Dosen','Total','Huruf','Tanggal']); foreach($rows as $n)fputcsv($out,[$n->mahasiswa->nim,$n->mahasiswa->nama,$n->dosen->nama,$n->total,Nilai::huruf($n->total),$n->tanggal]); fclose($out); return; }
}
